import ArcKitPlatform
import AppKit
import ApplicationServices
import Carbon.HIToolbox
import Darwin
import Foundation
import UniformTypeIdentifiers

enum ClipboardCapturePolicy {
    static let ownType = "com.archalo.arckit.clipboard"
    static let excludedTypes: Set<String> = [ownType, "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword", "com.apple.is-remote-clipboard"]
    static func permits(types: Set<String>, source: String, settings: ClipboardSettings) -> Bool {
        settings.isEnabled && excludedTypes.isDisjoint(with: types) && !types.contains(NSPasteboard.PasteboardType.fileURL.rawValue)
            && !settings.excludedApplications.contains(source)
    }
}

@MainActor
final class ClipboardSystemAccess {
    private let pasteboard: NSPasteboard
    init(pasteboard: NSPasteboard = .general) { self.pasteboard = pasteboard }
    var changeCount: Int { pasteboard.changeCount }

    func read(settings: ClipboardSettings) throws -> ClipboardItem? {
        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        let front = NSWorkspace.shared.frontmostApplication
        let source = pasteboard.string(forType: .init("org.nspasteboard.source")) ?? front?.bundleIdentifier ?? ""
        guard ClipboardCapturePolicy.permits(types: types, source: source, settings: settings) else { return nil }
        let content: ClipboardContent
        if types.contains(NSPasteboard.PasteboardType.png.rawValue) || types.contains(NSPasteboard.PasteboardType.tiff.rawValue) {
            guard let data = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff),
                  data.count <= ClipboardContent.maximumImageBytes,
                  ClipboardContent.hasSafeImageDimensions(data),
                  let image = NSBitmapImageRep(data: data), image.pixelsWide > 0, image.pixelsHigh > 0,
                  Double(image.pixelsWide) * Double(image.pixelsHigh) <= 40_000_000,
                  let png = image.representation(using: .png, properties: [:]) else { throw ClipboardError.invalidContent }
            content = ClipboardContent(kind: .image, png: png)
        } else if let text = pasteboard.string(forType: .string), !text.isEmpty {
            let url = URL(string: text)
            let link = url?.scheme.map { ["https", "http"].contains($0.lowercased()) } == true && !text.contains(where: \.isWhitespace)
            let rtf = pasteboard.data(forType: .rtf)
            content = ClipboardContent(kind: link ? .link : .text, text: text,
                rtf: (rtf?.count ?? 0) <= ClipboardContent.maximumTextBytes ? rtf : nil)
        } else { return nil }
        try content.validate()
        return ClipboardItem(content: content, sourceBundleID: source,
            sourceName: source == front?.bundleIdentifier ? (front?.localizedName ?? source) : source,
            deviceName: String((Host.current().localizedName ?? ProcessInfo.processInfo.hostName).prefix(255)))
    }

    func copy(_ content: ClipboardContent, plain: Bool) throws {
        try content.validate()
        let item = NSPasteboardItem()
        item.setString("1", forType: .init(ClipboardCapturePolicy.ownType))
        if let text = content.text { item.setString(text, forType: .string) }
        if !plain, let rtf = content.rtf { item.setData(rtf, forType: .rtf) }
        if let png = content.png { item.setData(png, forType: .png) }
        pasteboard.clearContents()
        guard pasteboard.writeObjects([item]) else { throw ClipboardError.invalidContent }
    }

    /// 只在用户点击“存到 Finder”时询问 Finder；不在打开历史面板时触发自动化权限。
    func finderDirectory() throws -> URL {
        let script = NSAppleScript(source: """
            tell application "Finder"
                if (count of windows) is 0 then error "No Finder window"
                return URL of (target of front window as alias)
            end tell
            """)
        var error: NSDictionary?
        guard let result = script?.executeAndReturnError(&error).stringValue, error == nil,
              let url = URL(string: result), url.isFileURL else { throw ClipboardError.noFinderWindow }
        var directory: ObjCBool = false
        guard FileManager.default.fileExists(atPath: url.path, isDirectory: &directory), directory.boolValue else { throw ClipboardError.noFinderWindow }
        return url
    }

    func paste(_ content: ClipboardContent, plain: Bool, target: NSRunningApplication?) async throws {
        guard let target, !target.isTerminated, target.bundleIdentifier != Bundle.main.bundleIdentifier else { throw ClipboardError.pasteTargetLost }
        guard AXIsProcessTrusted() else { throw ClipboardError.pastePermission }
        try copy(content, plain: plain)
        target.activate(options: [])
        // 等待已捕获的应用成为前台，不把粘贴发给迟到的其他窗口。
        for _ in 0..<10 {
            try await Task.sleep(for: .milliseconds(50))
            if NSWorkspace.shared.frontmostApplication?.processIdentifier == target.processIdentifier { break }
        }
        guard !target.isTerminated, NSWorkspace.shared.frontmostApplication?.processIdentifier == target.processIdentifier,
              let down = CGEvent(keyboardEventSource: nil, virtualKey: 9, keyDown: true),
              let up = CGEvent(keyboardEventSource: nil, virtualKey: 9, keyDown: false) else { throw ClipboardError.pasteTargetLost }
        down.flags = .maskCommand; up.flags = .maskCommand
        down.postToPid(target.processIdentifier); up.postToPid(target.processIdentifier)
    }
}

enum ClipboardFileWriter {
    /// 不覆盖原文件；原子 no-overwrite 发布，冲突顺延编号。
    static func save(_ content: ClipboardContent, directory: URL, markdown: Bool = false, now: Date = Date()) throws -> URL {
        try content.validate()
        let data = content.png ?? Data((content.text ?? "").utf8)
        let suffix = content.kind == .image ? "png" : (markdown ? "md" : "txt")
        let formatter = DateFormatter(); formatter.locale = Locale(identifier: "en_US_POSIX"); formatter.dateFormat = "yyyyMMdd-HHmmss"
        let base = "Clipboard-" + formatter.string(from: now)
        let staging = try FileManager.default.url(for: .itemReplacementDirectory, in: .userDomainMask,
            appropriateFor: directory.appendingPathComponent(base), create: true)
        defer { try? FileManager.default.removeItem(at: staging) }
        let output = staging.appendingPathComponent("content")
        try data.write(to: output)
        try ArcKitStoragePaths.secureFile(output)
        for index in 0..<1000 {
            let name = base + (index == 0 ? "" : "-\(index)") + "." + suffix
            let destination = directory.appendingPathComponent(name)
            if Darwin.renamex_np(output.path, destination.path, UInt32(RENAME_EXCL)) == 0 { return destination }
            let code = errno
            if code == EEXIST { continue }
            throw POSIXError(POSIXErrorCode(rawValue: code) ?? .EIO)
        }
        throw CocoaError(.fileWriteFileExists)
    }
}

@MainActor
final class ClipboardHotKey {
    private var handler: EventHandlerRef?
    private var reference: EventHotKeyRef?
    private var callback: (() -> Void)?
    private var generation: UInt32 = 0
    func stop() {
        generation &+= 1; callback = nil
        if let reference { UnregisterEventHotKey(reference) }; reference = nil
        if let handler { RemoveEventHandler(handler) }; handler = nil
    }
    func register(_ chord: HotKeyChord, action: @escaping () -> Void) -> OSStatus {
        stop()
        guard chord.isEnabled else { return noErr }
        guard chord.isSafeGlobalShortcut else { return OSStatus(paramErr) }
        callback = action
        var type = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: UInt32(kEventHotKeyPressed))
        let installed = InstallEventHandler(GetApplicationEventTarget(), { _, event, pointer in
            guard let event, let pointer else { return OSStatus(eventNotHandledErr) }
            var id = EventHotKeyID()
            guard GetEventParameter(event, EventParamName(kEventParamDirectObject), EventParamType(typeEventHotKeyID), nil,
                MemoryLayout<EventHotKeyID>.size, nil, &id) == noErr, id.signature == 0x414B434C else { return OSStatus(eventNotHandledErr) }
            let owner = Unmanaged<ClipboardHotKey>.fromOpaque(pointer).takeUnretainedValue()
            let generation = id.id
            Task { @MainActor in if owner.generation == generation { owner.callback?() } }
            return noErr
        }, 1, &type, Unmanaged.passUnretained(self).toOpaque(), &handler)
        guard installed == noErr else { stop(); return installed }
        var modifiers: UInt32 = 0
        if chord.modifiers.contains(.command) { modifiers |= UInt32(cmdKey) }
        if chord.modifiers.contains(.control) { modifiers |= UInt32(controlKey) }
        if chord.modifiers.contains(.option) { modifiers |= UInt32(optionKey) }
        if chord.modifiers.contains(.shift) { modifiers |= UInt32(shiftKey) }
        let status = RegisterEventHotKey(UInt32(chord.keyCode), modifiers, .init(signature: 0x414B434C, id: generation), GetApplicationEventTarget(), 0, &reference)
        if status != noErr { stop() }
        return status
    }
}
